/**
 * Embeds `@hewnui/site-url` DEFAULT_SITE_URL into consumers that must not
 * take a workspace runtime dependency (CLI pack / Next on Vercel).
 */
import { writeFileSync } from "fs";
import { dirname, join, relative } from "path";
import { fileURLToPath } from "url";
import { DEFAULT_SITE_URL } from "../packages/site-url/src/index";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");

const targets = [
  "packages/cli/src/lib/default-site-url.ts",
  "apps/web/lib/default-site-url.ts",
];

const contents = `/**
 * Generated by tooling/sync-site-url.ts — do not edit by hand.
 * Source of truth: packages/site-url/src/index.ts
 */
export const DEFAULT_SITE_URL = ${JSON.stringify(DEFAULT_SITE_URL)} as const;
`;

for (const rel of targets) {
  const outPath = join(repoRoot, rel);
  writeFileSync(outPath, contents);
  console.log(`sync:site-url → ${relative(repoRoot, outPath)} (${DEFAULT_SITE_URL})`);
}
